            WHEN U&'\1ffc' THEN U&'\03c9\03b9'
            WHEN U&'\fb00' THEN U&'\0066\0066'
            WHEN U&'\fb01' THEN U&'\0066\0069'
            WHEN U&'\fb02' THEN U&'\0066\006c'
            WHEN U&'\fb03' THEN U&'\0066\0066\0069'
            WHEN U&'\fb04' THEN U&'\0066\0066\006c'
            WHEN U&'\fb05' THEN U&'\0073\0074'
            WHEN U&'\fb06' THEN U&'\0073\0074'
            WHEN U&'\fb13' THEN U&'\0574\0576'
            WHEN U&'\fb14' THEN U&'\0574\0565'
            WHEN U&'\fb15' THEN U&'\0574\056b'
            WHEN U&'\fb16' THEN U&'\057e\0576'
            WHEN U&'\fb17' THEN U&'\0574\056d'
            ELSE c END, '' ORDER BY posicion)
        INTO v_texto FROM regexp_split_to_table(v_texto, '') WITH ORDINALITY AS partes(c, posicion);
    END IF;
    RETURN v_texto;
END $fn$;
